// Single place to configure the workflow. No secrets here.
const config = {
  // Google Sheet that receives the output (the long ID from the sheet URL).
  spreadsheetId: 'YOUR_SPREADSHEET_ID',
  // Any OpenAI-compatible chat completions endpoint. Default: Google Gemini.
  // To switch provider, change baseUrl + model and the Bearer credential.
  llmBaseUrl: 'https://generativelanguage.googleapis.com/v1beta/openai',
  // List the models your key can use: python scripts/smoke_test.py --models
  model: 'gemini-flash-latest',
  // Items older than this are ignored (keeps the first run small).
  maxAgeDays: 30,
  // Newest N items per source per run (protects free-tier rate limits).
  maxItemsPerSource: 6,
  // Public feeds, verified live on 2026-11-11.
  sources: [
    {
      name: 'UK OFSI',
      url: 'https://www.gov.uk/government/organisations/office-of-financial-sanctions-implementation.atom',
    },
    {
      name: 'EU Council',
      url: 'https://www.consilium.europa.eu/en/rss/pressreleases.ashx',
    },
    {
      name: 'US Federal Reserve Enforcement',
      url: 'https://www.federalreserve.gov/feeds/press_enforcement.xml',
    },
  ],
};

// One item per feed, so a single RSS Read node fetches them all.
// Every item also carries the full config for later nodes: $('Config').first().json
return config.sources.map((s) => ({ json: { ...config, name: s.name, url: s.url } }));

// Clean feed items, tag the source, drop old ones, keep newest N per source.
const cfg = $('Config').first().json;
const host = (u) => (String(u).match(/^https?:\/\/([^/?#]+)/i) || [])[1] || '';
const sourceFor = (link) => (cfg.sources.find((s) => host(s.url) === host(link)) || { name: 'Unknown' }).name;
const clean = (t) => String(t || '').replace(/<[^>]+>/g, ' ').replace(/\s+/g, ' ').trim();
const cutoff = Date.now() - cfg.maxAgeDays * 86400000;

const rows = [];
for (const item of $input.all()) {
  const j = item.json;
  const link = clean(j.link);
  if (!link) continue;
  const rawDate = j.isoDate || j.pubDate || j['a10:updated'] || '';
  const ts = Date.parse(rawDate);
  if (!Number.isNaN(ts) && ts < cutoff) continue;
  rows.push({
    source: sourceFor(link),
    title: clean(j.title),
    link,
    summary: clean(j.contentSnippet || j.content || j.summary).slice(0, 2000),
    published: Number.isNaN(ts) ? '' : new Date(ts).toISOString(),
  });
}

const perSource = {};
const out = [];
for (const r of rows.sort((a, b) => (b.published || '').localeCompare(a.published || ''))) {
  perSource[r.source] = (perSource[r.source] || 0) + 1;
  if (perSource[r.source] <= cfg.maxItemsPerSource) out.push({ json: r });
}
return out;

// Runs once per loop iteration (batch size 1). Starts the timer and builds the LLM request.
const SYSTEM_PROMPT = "You are a content editor for a B2B compliance technology audience: compliance officers, MLROs and financial-crime teams at banks and fintechs.\n\nYou receive ONE news item from an official public source (title, short summary, source name, publication date). Turn it into draft marketing content and score its relevance.\n\n## Hard rules\n1. Use ONLY facts that appear in the news item. Do not add names, numbers, dates, amounts, legal references, causes or consequences that are not in the item.\n2. If the item gives few details, write less. Never fill gaps with assumptions. Never speculate about what a regulator \"will\" do.\n3. The three action points are practical checks a compliance team could run in response to this kind of item (for example re-screening, reviewing a licence, updating a control). Phrase them as actions to consider, not as facts about the news.\n4. Tone: plain, professional B2B English. No hype, no superlatives, no emojis, no hashtags, no exclamation marks.\n5. Do not mention any vendor, product or company that is not in the news item. Do not write a sales pitch.\n6. Do not include any URL. The source link is appended automatically after you answer.\n7. Return only the JSON object described by the response schema.\n\n## Output fields\n- `linkedin_post`: at most 120 words. Structure: one hook sentence, then exactly three takeaways (each on its own line, starting with \"- \"), then one closing question to the reader.\n- `newsletter_blurb`: at most 60 words. One short paragraph.\n- `one_pager_md`: Markdown with exactly these sections, in this order:\n  `# <headline>`, `## What happened`, `## Who is affected`, `## 3 actions for compliance teams` (numbered list of three).\n- `relevance_score`: integer 0-10. How much does this item matter to compliance teams at banks and fintechs?\n  - 9-10: new or changed sanctions designations, AML/CFT rules or enforcement that require action from most regulated firms.\n  - 6-8: guidance, licences, enforcement against a single firm, or changes that affect a clear subset of firms.\n  - 3-5: loosely related (general foreign-policy statements, procedural updates with no clear compliance impact).\n  - 0-2: not related to sanctions, AML/CFT, KYC/KYB, fraud or financial-crime compliance.\n- `relevance_reason`: one sentence, at most 30 words, explaining the score.\n\nIf the item is not related to financial-crime compliance, still return all fields, keep them short, and give a low score.";
const OUTPUT_SCHEMA = {"type": "object", "properties": {"linkedin_post": {"type": "string", "description": "Max 120 words. Hook sentence, three takeaways each on its own line starting with '- ', then one closing question. No URLs."}, "newsletter_blurb": {"type": "string", "description": "Max 60 words. One short paragraph. No URLs."}, "one_pager_md": {"type": "string", "description": "Markdown: '# headline', '## What happened', '## Who is affected', '## 3 actions for compliance teams' (numbered list of three). No URLs."}, "relevance_score": {"type": "integer", "description": "0-10. Importance for compliance teams at banks and fintechs."}, "relevance_reason": {"type": "string", "description": "One sentence, max 30 words, explaining the score."}}, "required": ["linkedin_post", "newsletter_blurb", "one_pager_md", "relevance_score", "relevance_reason"]};

const n = $input.first().json;
const userText = [
  'NEWS ITEM',
  `Source: ${n.source}`,
  `Published: ${n.published || 'not stated'}`,
  `Title: ${n.title}`,
  `Summary: ${n.summary || '(no summary provided)'}`,
].join('\n');

return [
  {
    json: {
      ...n,
      t0: Date.now(),
      body: {
        model: $('Config').first().json.model,
        temperature: 0.2,
        messages: [
          { role: 'system', content: SYSTEM_PROMPT },
          { role: 'user', content: userText },
        ],
        response_format: {
          type: 'json_schema',
          json_schema: { name: 'content_drafts', strict: true, schema: OUTPUT_SCHEMA },
        },
      },
    },
  },
];

// Parse the LLM answer, run deterministic QA checks, shape the row for Google Sheets.
const news = $('Build Prompt').first().json;
const res = $input.first().json;
const seconds = Math.round((Date.now() - news.t0) / 100) / 10;

const pad = (x) => String(x).padStart(2, '0');
const now = new Date();
const date = `${now.getUTCFullYear()}-${pad(now.getUTCMonth() + 1)}-${pad(now.getUTCDate())} ${pad(now.getUTCHours())}:${pad(now.getUTCMinutes())}:${pad(now.getUTCSeconds())}`;
const monday = new Date(Date.UTC(now.getUTCFullYear(), now.getUTCMonth(), now.getUTCDate() - ((now.getUTCDay() + 6) % 7)));
const weekStart = monday.toISOString().slice(0, 10);

const row = {
  date,
  source: news.source,
  title: news.title,
  link: news.link,
  score: '',
  score_reason: '',
  linkedin_post: '',
  newsletter_blurb: '',
  one_pager_md: '',
  status: 'draft',
  generation_seconds: seconds,
  week_start: weekStart,
  qa_flags: '',
};

let out;
try {
  const text = res.choices[0].message.content;
  out = JSON.parse(text);
} catch (e) {
  row.status = 'error';
  row.qa_flags = `llm_error: ${String((res.error && (res.error.message || JSON.stringify(res.error))) || e.message).slice(0, 200)}`;
  return [{ json: row }];
}

const flags = [];
const words = (t) => String(t || '').trim().split(/\s+/).filter(Boolean).length;
const score = Number(out.relevance_score);
if (!Number.isInteger(score) || score < 0 || score > 10) flags.push('score_out_of_range');
if (words(out.linkedin_post) > 120) flags.push(`linkedin_over_120_words(${words(out.linkedin_post)})`);
if (words(out.newsletter_blurb) > 60) flags.push(`newsletter_over_60_words(${words(out.newsletter_blurb)})`);
for (const h of ['## What happened', '## Who is affected', '## 3 actions for compliance teams']) {
  if (!String(out.one_pager_md || '').includes(h)) flags.push(`one_pager_missing_section(${h.slice(3)})`);
}

// Grounding check: every number in the drafts must appear in the source text.
const generated = [out.linkedin_post, out.newsletter_blurb, out.one_pager_md].join('\n');
const numbers = (t) => (String(t).replace(/^\s*\d+[.)]\s/gm, '').match(/\d[\d.,/]*\d|\d/g) || []).map((x) => x.replace(/,/g, ''));
const sourceNumbers = new Set(numbers(`${news.title} ${news.summary} ${news.published}`));
const unknown = [...new Set(numbers(generated))].filter((x) => !sourceNumbers.has(x) && x !== '3');
if (unknown.length) flags.push(`number_not_in_source(${unknown.slice(0, 5).join(' ')})`);
if (/https?:\/\//i.test(generated)) flags.push('model_added_url');

// The source link is appended here, not by the model, so it can never be wrong or missing.
const src = `Source: ${news.link}`;
row.score = Number.isFinite(score) ? score : '';
row.score_reason = String(out.relevance_reason || '');
row.linkedin_post = `${String(out.linkedin_post || '').trim()}\n\n${src}`;
row.newsletter_blurb = `${String(out.newsletter_blurb || '').trim()} ${src}`;
row.one_pager_md = `${String(out.one_pager_md || '').trim()}\n\n---\n${src} (${news.source})`;
row.qa_flags = flags.join('; ');
return [{ json: row }];
